{
  "sources": [
    {
      "id": "src-exploratorium-gears",
      "title": "Exploratorium - Science of Cycling: Gears",
      "url": "https://www.exploratorium.edu/cycling/gears1.html"
    },
    {
      "id": "src-britannica-bicycle",
      "title": "Encyclopaedia Britannica - Bicycle",
      "url": "https://www.britannica.com/technology/bicycle"
    },
    {
      "id": "src-openstax-college-physics",
      "title": "OpenStax - College Physics 2e",
      "url": "https://openstax.org/details/books/college-physics-2e"
    }
  ],
  "misconceptionNotes": [],
  "sections": [
    {
      "id": "what-youre-seeing",
      "claims": [
        {
          "id": "claim-seeing-1",
          "text": "A bike has pedals connected to a front ring, a chain, and round cogs on the back wheel.",
          "sourceIds": [
            "src-exploratorium-gears",
            "src-britannica-bicycle"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-seeing-2",
          "text": "Changing gears moves the chain to a different front ring or back cog.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "short-answer",
      "claims": [
        {
          "id": "claim-short-1",
          "text": "A low gear makes pedaling up a hill easier because each pedal push needs less force, but you must pedal more times and move less far with each pedal turn.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "first-principles",
      "claims": [
        {
          "id": "claim-principles-1",
          "text": "Going uphill lifts you and the bike higher, so your legs must do work against gravity.",
          "sourceIds": [
            "src-openstax-college-physics"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-principles-2",
          "text": "Gears trade force for turns: less push on each pedal means more pedal turns are needed to cover the same climb.",
          "sourceIds": [
            "src-openstax-college-physics",
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "how-parts-work",
      "claims": [
        {
          "id": "claim-parts-1",
          "text": "Your legs turn the pedals and front ring, and the chain carries that turning to a cog that turns the back wheel.",
          "sourceIds": [
            "src-britannica-bicycle",
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-parts-2",
          "text": "A small front ring with a big back cog is an easy hill gear: the back wheel turns fewer times for each pedal turn, but pedaling needs less push.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-parts-3",
          "text": "A big front ring with a small back cog makes the back wheel turn more for each pedal turn, which can help go faster on flat ground but needs a harder push.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "try-an-idea",
      "claims": [
        {
          "id": "claim-try-1",
          "text": "Try this with a grown-up on a safe flat path: ride the same short distance first in an easy gear and then in a harder gear, and compare how many pedal turns you count and how hard you must push.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "history",
      "claims": [
        {
          "id": "claim-history-1",
          "text": "Some early bicycles had one very big front wheel driven directly by the pedals, which made them hard to mount and ride.",
          "sourceIds": [
            "src-britannica-bicycle"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-history-2",
          "text": "Later safety bicycles used a chain to drive the rear wheel, like most bikes today.",
          "sourceIds": [
            "src-britannica-bicycle"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "check-thinking",
      "claims": [
        {
          "id": "claim-check-1",
          "text": "Question: If an easy gear needs less push, why not use it all the time?",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-check-2",
          "text": "Answer: In an easy gear you spin many pedal turns but move only a little with each turn, so you would be slow on flat ground.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    },
    {
      "id": "go-further",
      "claims": [
        {
          "id": "claim-further-1",
          "text": "With the bike still and a grown-up helping, count teeth on the front ring and back cog to see which pairs make easy gears and which make hard gears.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        },
        {
          "id": "claim-further-2",
          "text": "Turn the pedals slowly once by hand and count how many times the back wheel turns in different gears.",
          "sourceIds": [
            "src-exploratorium-gears"
          ],
          "uncertainty": null
        }
      ]
    }
  ]
}
